\label{L: properties of box norms}
Let $\delta\in(0, 1)$, let $d,D,N, s\in{\mathbb N}$,
and let $E_1, \ldots, E_s\subseteq {\mathbb Z}^D$ be finite {and nonempty} sets. Let $f:{\mathbb Z}^D\to{\mathbb C}$ be a $1$-bounded function supported on $[N]^D$. Then the following properties hold:
\begin{enumerate}
    \item\label{i: inductive formula} (Inductive formula) For any $i\in\{1, \ldots, s\}$, we have
    \begin{align*}
        \norm{f}_{E_1, \ldots, E_s}^{2^s} = \mathbb{E}_{{\mathbf{h}}_1, {\mathbf{h}}_1'\in E_1}\cdots \mathbb{E}_{{\mathbf{h}}_i, {\mathbf{h}}_i'\in E_i}\norm{\Delta'_{({\mathbf{h}}_1, {\mathbf{h}}_1'), \ldots,\; ({\mathbf{h}}_i, {\mathbf{h}}_i')}f}_{E_{i+1}, \ldots, E_s}^{2^{s-i}}.
    \end{align*}
    \item\label{i: permutation invariance} (Permutation invariance) For any permutation $\sigma$ on $\{1, \ldots, s\}$, we have 
    \begin{align*}
        \norm{f}_{E_1, \ldots, E_s} = \norm{f}_{E_{\sigma(1)}, \ldots, E_{\sigma(s)}}.
    \end{align*}
    \item\label{i: monotonicity} (Monotonicity) If $f$ is $1$-bounded and $|[N]^D-E_s|\leq C N^D$ for some $C>0$, then 
    \begin{align}\label{E: monotonicity}
        \norm{f}_{E_1, \ldots, E_{s-1}}^{2^{s-1}}\geq \delta N^D \quad \Longrightarrow \quad \norm{f}_{E_1, \ldots, E_{s}}^{2^{s}}\geq \delta^2 N^D/C.
    \end{align}
    \item\label{i: enlarging} (Enlarging the sets) If $s\geq 2$ and $E'_i\subseteq {\mathbb Z}^D$ is a finite set satisfying $E'_i \supseteq E_i$ for each $i\in\{1,\ldots, s\}$, then 
    \begin{align*}
        \norm{f}_{E_1, \ldots, E_s}\leq \brac{\frac{|E_1'|\cdots|E_s'|}{|E_1|\cdots|E_s|}}^{1/2^{s-1}}\norm{f}_{E_1', \ldots, E_s'}.
    \end{align*}
    \item\label{i: trimming 2} (Trimming the lengths of boxes)  
    Let
    \begin{align*}
        E_i = {\boldsymbol{\beta}}_{i}\cdot[\pm H_{i}]\quad \textrm{and}\quad E_i' = {\boldsymbol{\beta}}_{i}\cdot[\pm \kappa_{i} H_{i}]
    \end{align*}
    for some ${\boldsymbol{\beta}}_{i}\in {\mathbb Z}^D$, $\kappa_{i}>0$, and $H_{i}\in {\mathbb N}$. If $f$ is $1$-bounded, then
    \begin{align*}
        \norm{f}_{E_1, \ldots, E_s}^{2^s}\geq \delta N^D\quad \Longrightarrow\quad        \norm{f}_{E_1', \ldots, E_s'}^{2^s}\gg_{s}\delta^{2^s}\min(1, \delta^{2^s}/\kappa)^{2s} N^D
    \end{align*}
    for $\kappa = \max_{i}\kappa_{i}.$
    \item\label{i: passing to APs} (Passing to sub-arithmetic progressions) Suppose that  $f$ is $1$-bounded and
    \begin{align*}
        E_i = {\boldsymbol{\beta}}_{i}\cdot[\pm H_{i}]\quad \textrm{and}\quad E_i' = q_{i}{\boldsymbol{\beta}}_{i}\cdot[\pm H_{i}/q_{i}]
    \end{align*}
    for some ${\boldsymbol{\beta}}_{i}\in {\mathbb Z}^D$ and $q_{i}, H_{i}\in{\mathbb N}$ satisfying $q_{i}\leq C \delta^{2^s}H_{i}$ for all $i$ and some constant $C>0$.
    Then
    \begin{align*}
        \norm{f}_{E_1, \ldots, E_s}^{2^s}\geq \delta N^D \quad \Longrightarrow\quad        \norm{f}_{E_1', \ldots, E_s'}^{2^s}\gg_{s,C} \delta N^D.
    \end{align*}
\end{enumerate}

