\smallskip
\textbf{Step 1: Replacing $\widetilde{f_2}$ by a box norm obstruction.}
\smallskip

Our first objective is to use Proposition \ref{prop:lambda_1} in conjunction with relevant box norm inverse theorems and stashing to replace $\widetilde{f_2}$ by a ``structured'' function.
By Proposition \ref{prop:lambda_1}, we have the lower bound
$$\|\widetilde{f_2}\|_{({\mathbf{e}}_2-{\mathbf{e}}_1)\cdot [\pm N/V],\; {\mathbf{e}}_1\cdot[\pm N/V]}^4 \gg \delta^{O(1)}(N/V)^2.$$
The stashing argument gives
$$\|\mathcal{D}'_2(a, \widetilde{f_1})\|_{({\mathbf{e}}_2-{\mathbf{e}}_1)\cdot [\pm N/V],\; {\mathbf{e}}_1\cdot  [\pm N/V]}^4 \gg \delta^{O(1)}(N/V)^2,$$
for the dual function
\begin{multline*}
\mathcal{D}'_{2}(a, \widetilde{f_1})(x,y):=\mathbb{E}_{z \in [(N/W_d)^{1/d}V^{-1}]}e(a(y-\widetilde{P}_{[r, V]}(z))x)\\
\widetilde{f_1}(x+\widetilde{P}_{[r, V]}(z),y-\widetilde{P}_{[r, V]}(z))1_{[N/V]}(y),
\end{multline*}
where we were able to insert the term $1_{[N/V]}$ because $\widetilde{f_2}$ is supported on $[N/V]^2.$
By the inverse theorem for the $U^1\times U^1$-box norm (Lemma \ref{L: U1xU1 inverse}), there are $1$-bounded functions $b_1, b_2:{\mathbb Z}\to{\mathbb C}$ such that 
\begin{multline*}
\sum_{x, y} \mathbb{E}_{z \in [(N/W_d)^{1/d}V^{-1}]} b_1(y) b_2(x+y) e(a(y - \widetilde{P}_{[r,V]}(z))x)\\
\widetilde{f_1}(x + \widetilde{P}_{[r,V]}(z), y - \widetilde{P}_{[r,V]}(z))1_{[N/V]}(y) \gg \delta^{O(1)}(N/V)^2,    
\end{multline*}
and the presence of the $1_{[N/V]}(y)$ term lets us assume that $b_1$ is supported on $[N/V]$.
The change of variables 
$y \mapsto y + \widetilde{P}_{[r,V]}(z)$ gives
\begin{multline*}
\sum_{x, y}\mathbb{E}_{z \in [(N/W_d)^{1/d}V^{-1}]} e(a(y)x)
\widetilde{f_1}(x+ \widetilde{P}_{[r,V]}(z), y)\\
b_1(y+ \widetilde{P}_{[r,V]}(z)) b_2(x + y + \widetilde{P}_{[r,V]}(z)) \gg \delta^{O(1)}(N/V)^2.
\end{multline*}
We observe that $b_2(x + y + \widetilde{P}_{[r,V]}(z))$ is a function of $(x+\widetilde{P}_{[r,V]}(z), y)$. Shifting $x\mapsto x - \widetilde{P}_{[r,V]}(z)$ and setting $\widetilde{f_1}'(x,y):= e(a(y)x)\widetilde{f_1}(x,y)b_2(x + y)$, we get 
\begin{align*}
\sum_{x, y}\mathbb{E}_{z \in [(N/W_d)^{1/d}V^{-1}]} e(-a(y)\widetilde{P}_{[r,V]}(z))
\widetilde{f_1}'(x, y)
b_1(y+ \widetilde{P}_{[r,V]}(z))  \gg \delta^{O(1)}(N/V)^2.
\end{align*}
Recall that $\widetilde{f_1}'$ is 1-bounded and supported on $[N/V]^2$.  Using the triangle inequality in the $x$- and $y$-variables, we can eliminate $\widetilde {f_1}'$ entirely and obtain
\begin{align*}
\sum_{y\in[N/V]}\abs{\mathbb{E}_{z \in [(N/W_d)^{1/d}V^{-1}]} e(-a(y)\widetilde{P}_{[r,V]}(z))
b_1(y+ \widetilde{P}_{[r,V]}(z))}\gg \delta^{O(1)}N/V.
\end{align*}
We have thus reduced matters to analyzing the auxiliary operator
\begin{align}\label{E: Lambda''}
    \Lambda''(b_1):= \sum_{y\in[N/V]}\abs{\mathbb{E}_{z \in [(N/W_d)^{1/d}V^{-1}]} e(-a(y)\widetilde{P}_{[r,V]}(z))
b_1(y+ \widetilde{P}_{[r,V]}(z))}.
\end{align}

\smallskip
\textbf{Step 2: Replacing $b_1$ by a nilsequence.}
\smallskip

Our next goal is to show that $\Lambda''$ can be controlled by a Gowers norm of $b_1$; this will let us replace $b_1$ by a nilsequence (at least on arithmetic progressions of not-too-small difference). To obtain Gowers norm control, we observe that $\Lambda''$ is amenable to a standard PET argument.  Let $b_3:{\mathbb Z}\to{\mathbb C}$ be a $1$-bounded function supported on $[N/V]$ such that 
$$\Lambda''(b_1) = \sum_{y}b_3(y)\mathbb{E}_{z \in [(N/W_d)^{1/d}V^{-1}]} e(-a(y)\widetilde{P}_{[r,V]}(z))
b_1(y+ \widetilde{P}_{[r,V]}(z)) \gg \delta^{O(1)}N/V.$$
Shifting $y \mapsto y-\widetilde P_{[r,V]}(z)$, stashing, and shifting back $y \mapsto y+\widetilde P_{[r,V]}(z)$, we find that
$$\sum_{y}\overline{b_3(y)}\mathbb{E}_{z \in [(N/W_d)^{1/d}V^{-1}]} e(a(y)\widetilde{P}_{[r,V]}(z))
\widetilde b_1(y+ \widetilde{P}_{[r,V]}(z))\gg \delta^{O(1)}N/V,$$
where
$$\widetilde b_1(y):= \mathbb{E}_{z \in [(N/W_d)^{1/d}V^{-1}]} e(-a(y-\widetilde{P}_{[r,V]}(z))\widetilde{P}_{[r,V]}(z))
b_3(y-\widetilde{P}_{[r,V]}(z))1_{[N/V]}(y).$$ Note that the indicator function $1_{[N/V]}(y)$ can be included since $b_1$ is supported on this set. 
Now, using the Cauchy--Schwarz inequality to double the $z$-variable $d+1$ times (in the style of PET), we eliminate $b_3(y)$ and the exponential involving $a(y)$; we obtain
\begin{multline*}
    \sum_{y, h_1, \ldots, h_{d+1}}\mu_{(N/W_d)^{1/d}V^{-1}}(h_1, \ldots, h_{d+1})\\ \mathbb{E}_{z \in [(N/W_d)^{1/d}V^{-1}]} \prod_{{\underline{\epsilon}}\in\{0,1\}^{d+1}}{\mathcal C}^{|{\underline{\epsilon}}|}\widetilde b_1(y + \widetilde{P}_{[r,V]}(z+{\underline{\epsilon}}\cdot{\underline{h}})) \gg \delta^{O(1)}N/V.
\end{multline*}
By \cite[Proposition 10.1]{KKL24a} and the formula $V_d = \beta_d \beta_1^{d-2}V^{d-1}W^{d-1}$, we have
\begin{align*}
    \norm{\widetilde b_1}_{U^{k+1}(V_d\cdot[\pm N/(VV_d)])}^{2^{k+1}}\gg \delta^{O(1)} N/V
