   |B| \geq C_2\cdot(N/(\tilde{V}\tilde{V}_d))^{1/d}(M/\delta)^{-C_2 m^{C_2}}.
\end{align}

If
\begin{equation}\label{E:Wtricknilsequencehypothesis}
