    \begin{align}\label{E: lower bound for model}
        \Lambda^{{\mathrm{Model}}}(f_0, f_1, f_2)\geq \delta N^3,
    \end{align}
    then $\norm{f_0}^4_{{\mathbf{e}}_1\cdot[\pm N],\; {\mathbf{e}}_2\cdot[\pm N]}, \norm{f_1}^4_{{\mathbf{e}}_1\cdot[\pm N],\; ({\mathbf{e}}_2-{\mathbf{e}}_1)\cdot[\pm N]}, \norm{f_2}^4_{{\mathbf{e}}_2\cdot[\pm N],\; ({\mathbf{e}}_2-{\mathbf{e}}_1)\cdot[\pm N]}\gg_d \delta^{O_d(1)} N^2$.

\begin{align}\label{E: lower bound for model}
