\label{P: Lambda*}
    There exists $C = C(P)>0$ such that the following holds. Let $f_0, f_1, f_2:{\mathbb Z}^2\to{\mathbb C}$ be $1$-bounded functions supported on $[N]^2$. If $N, W$ satisfy $N\geq C W^{C}$ and $W\geq \exp\exp(\log(1/\delta)^{C})$, then
    \begin{align*}
        |\Lambda^W(f_0,f_1,f_2)-\Lambda^{\mathrm{Model}}(f_0,f_1,f_2)| <\delta N^2.
    \end{align*}

We let all constants depend on $P$.
Define the ``difference'' counting operator
\begin{align*}
    \Lambda^*(f_0, f_1, f_2) := \Lambda^W(f_0,f_1,f_2)-\Lambda^{\mathrm{Model}}(f_0,f_1,f_2)
\end{align*}
and the dual function
\begin{align*}
    {\mathcal D}_0^*(f_1, f_2)(x,y) &:= \mathbb{E}_{z\in[(N/W_d)^{1/d}]}f_1(x + \widetilde P(z), y) f_2(x, y + \widetilde P(z))\\
    &\qquad\qquad- \mathbb{E}_{z\in[N]}f_1(x + z, y) f_2(x, y + z)\nu(z).
\end{align*}
Assume for the sake of contradiction that
\begin{align*}
    |\Lambda^*(f_0, f_1, f_2)|\geq \delta N^2;
\end{align*}
then stashing gives
\begin{align*}
    |\Lambda^*({\mathcal D}_0^*(f_1,f_2), f_1, f_2)|\geq \delta^2 N^2,
\end{align*}
and we conclude by the triangle inequality that either
\begin{align*}
    |\Lambda^W({\mathcal D}_0^*(f_1,f_2), f_1, f_2)|\geq \delta^2 N^2/2 \quad\textrm{or}\quad |\Lambda^{\mathrm{Model}}({\mathcal D}_0^*(f_1,f_2), f_1, f_2)|\geq \delta^2 N^2/2.
\end{align*}
According to which of these inequalities holds, we apply either
Theorem \ref{thm:degree lowering-lambda} or Proposition \ref{P: box norm control of model} and Lemma \ref{L: properties of box norms}\eqref{i: passing to APs} to find a positive integer power $V = W^{O(1)}$ for which 
\begin{align*}
    \norm{{\mathcal D}_{0}^*(f_1,f_2)}_{{\mathbf{e}}_1 V \cdot[\pm N/V],\; {\mathbf{e}}_2 V \cdot[\pm N/V]}^4 \geq \exp(-\log(1/\delta)^{O(1)})N^2.
\end{align*}
As usual, we must pass to arithmetic progressions of difference $V$ before using the $U^1 \times U^2$-inverse theorem. Write $g_{0, j_1, j_2}:= ({\mathcal D}_0^*(f_1, f_2))_{(j_1, j_2, V)}$, so that
\begin{align*} 
    \mathbb{E}_{j_1, j_2\in[V]}\norm{g_{0, j_1, j_2}}_{{\mathbf{e}}_1 \cdot[\pm N/V],\; {\mathbf{e}}_2 \cdot[\pm N/V]}^4 \geq \exp(-\log(1/\delta)^{O(1)})(N/V)^2.
\end{align*}

The inverse theorem for the $U^1 \times U^1$-box norm (Lemma \ref{L: U1xU1 inverse}) gives $1$-bounded functions $b_{1, j_1, j_2},b_{2, j_1, j_2}: \mathbb{Z} \to \mathbb{C}$, for each $j_1, j_2\in [V]$, such that
\begin{align*}
    \mathbb{E}_{j_1, j_2\in[V]}\sum_{x,y}g_{0, j_1, j_2}(x,y)b_{1, j_1, j_2}(x)b_{2, j_1, j_2}(y)\geq \exp(-\log(1/\delta)^{O(1)})(N/V)^2.
\end{align*}

Define the weights
\begin{align*}
    \tilde{\nu}(z):= \frac{N}{(N/W_d)^{1/d}}1_{\widetilde P([(N/W_d)^{1/d}])}(z)\quad\textrm{and}\quad \nu^*: = \Tilde{\nu}-\nu,
\end{align*}
so that
\begin{align*}
    \mathbb{E}_{z\in[(N/W_d)^{1/d}]}f_1(x + \widetilde P(z), y)f_2(x, y + \widetilde P(z)) = \mathbb{E}_{z\in[N]} f_1(x+z, y) f_2(x, y+z)\Tilde{\nu}(z)
\end{align*}
and
\begin{align*}
    {\mathcal D}_0^*(f_1, f_2)(x,y) = \mathbb{E}_{z\in[N]} f_1(x+z, y) f_2(x, y+z)\nu^*(z).
\end{align*}
Then
\begin{multline*}
    \mathbb{E}_{j_1,j_2,r\in[V]}\sum_{x,y}\mathbb{E}_{z\in[N/V]}b_{1,j_1,j_2}(x)b_{2,j_1,j_2}(y)\\
    f_{1, j_1 + r, j_2}(x+z,y)f_{2,j_1,j_2+r}(x,y+z)\nu^*_r(z)\geq \exp(-\log(1/\delta)^{O(1)})(N/V)^2, 
\end{multline*}
where $f_{l,j_1,j_2} :=(f_l)_{(j_1,j_2, V)}$ and $\nu^*_r := \nu^*_{(r,V)}$.

We will now deduce the largeness of the norm $\norm{\nu^*}_{U^2(V\cdot[\pm N/V])}$, in contradiction with the Fourier-uniformity estimate from Proposition \ref{prop:nu-uniformity}.  After shifting $x\mapsto x-z$, we use the Cauchy--Schwarz inequality and Lemma~\ref{L: vdC} in order to double $z$, obtaining
\begin{multline*}
    \mathbb{E}_{j_1,j_2,r\in[V]}\sum_{x,y,h_1}\mathbb{E}_{z\in[N/V]} \mu_{N'/V}(h_1)\Delta_{-h_1}b_{1,j_1,j_2}(x-z)\\
    \Delta_{h_1({\mathbf{e}}_2-{\mathbf{e}}_1)}f_{2,j_1+r,j_2}(x-z,y+z)\Delta_{h_1} \nu^*_r(z)\geq \exp(-\log(1/\delta)^{O(1)})(N/V)^2
\end{multline*}
for any positive integer $ N'\leq \exp(-\log(1/\delta)^{O(1)}) N$. Shifting $(x,y)\mapsto (x+z, y-z)$ and repeating this maneuver gives
\begin{align*}
    \mathbb{E}_{r\in[V]}\norm{\nu^*_r}_{U^2([\pm N'/V])}^4 = \mathbb{E}_{r\in[V]}\sum_{z,h_1,h_2}\mu_{N'/V}(h_1,h_2)\Delta_{h_1,h_2}\nu^*_r(z)\geq \exp(-\log(1/\delta)^{O(1)})N/V.
\end{align*}
Choosing $N'\asymp \exp(-\log(1/\delta)^{C}) N$ for a sufficiently large constant $C>0$, we can 
