\label{L: 1-dim U^1 inverse}
    Let $\delta\in(0, 1]$ and $N, N'\in{\mathbb N}$ with $N'\geq \delta^{-1/2} N\geq \delta^{-1}$.  If $f: {\mathbb Z} \to \mathbb{C}$ is a $1$-bounded function supported on $[N]$, then
    \begin{gather*}
        \norm{f}_{[\pm N']}^2\geq \delta N \quad \Longrightarrow\quad \abs{\sum_{x}f(x)}\gg\delta^{1/4} N.
    \end{gather*}

By definition, we have
\begin{align*}
    \norm{f}_{[\pm N']}^2 = \sum_{x,x'\in[N]}\mu_{N'}(x'-x)f(x)\overline{f(x')}.
\end{align*}
The idea is that since $N'$ is sufficiently large relative to $N$, we have $\mu_{N'}(x-x') \approx 1/(2N'-1)$ for all $x,x'\in[N]$.  More precisely, since $f$ is $1$-bounded and $N' \geq \delta^{-1/2}N \geq N$, we can make the crude comparison
\begin{align*}
\abs{(2N'-1)\norm{f}_{[N']}^2 -\sum_{x,x'}f(x)\overline{f(x')}} &\leq \sum_{x,x'\in[N]}\abs{(2N'-1)\mu_{N'}(x'-x)-1}\\
 &=\frac{1}{2N'-1} \sum_{x,x' \in [N]} |x-x'|\\
 & \leq \frac{N^2(N-1)}{2N'-1} \leq \delta^{1/2} N^2/2.
\end{align*}
Hence
\begin{align*}
\abs{\sum_x f(x)}^2=\sum_{x,x'} f(x) \overline{f(x')} &\geq (2N'-1) \delta N-\delta^{1/2} N^2/2\\
&\geq(3/2)\delta^{1/2}N - \delta N\gg \delta^{1/2}N^2
\end{align*}
since $N\geq\delta^{-1/2}$.

\label{L: normalized vs. unnormalized}
        Let $s\geq 2$, let $D, H_1, \ldots, H_s\in{\mathbb N}$, and let ${\textbf{v}}_1, \ldots, {\textbf{v}}_s\in{\mathbb Z}^D$.  For any compactly supported function $f:{\mathbb Z}^D\to{\mathbb C}$, we have
            \begin{align*}
                \norm{f}_{{\textbf{v}}_1\cdot[\pm H_1],\ldots, {\textbf{v}}_s\cdot[\pm H_s]}^{2^s}\leq \prod_{i=1}^s \frac{1}{2H_i-1} \cdot\norm{f}_{{\textbf{v}}_1, \ldots, {\textbf{v}}_s}^{2^{s}}.
            \end{align*}

Using the inductive formula for box norms, the pointwise bound $\mu_{H}(h) \leq 1/(2H-1)$, and nonnegativity, we have
\begin{align*}
\norm{f}_{{\textbf{v}}_1\cdot[\pm H_1],\ldots, {\textbf{v}}_s\cdot[\pm H_s]}^{2^s} &= \sum_{h_2, \ldots, h_s}\mu_{H_2}(h_2) \cdots \mu_{H_s}(h_s)\norm{\Delta_{{\textbf{v}}_2 h_2, \ldots, {\textbf{v}}_s h_s} f}_{{\textbf{v}}_1\cdot[\pm H_1]}^2\\
&\leq \prod_{i=2}^s \frac{1}{2H_i-1} \cdot\sum_{h_2, \ldots, h_s}\norm{\Delta_{{\textbf{v}}_2 h_2, \ldots, {\textbf{v}}_s h_s} f}_{{\textbf{v}}_1\cdot[\pm H_1]}^{2}\\
 &=\prod_{i=2}^s \frac{1}{2H_i-1} \cdot \sum_{h_1} \mu_{H_1}(h_1)\norm{\Delta_{{\textbf{v}}_1 h_1}f}_{{\textbf{v}}_2, \ldots, {\textbf{v}}_s}^{2^{s-1}}\\
 & \leq \prod_{i=1}^s \frac{1}{2H_i-1} \cdot \norm{f}_{{\textbf{v}}_1, \ldots, {\textbf{v}}_s}^{2^{s}};
\end{align*}
note that the applications of nonnegativity crucially used the assumption $s \geq 2$.

\begin{align*}
\norm{f}_{{\textbf{v}}_1\cdot[\pm H_1],\ldots, {\textbf{v}}_s\cdot[\pm H_s]}^{2^s} &= \sum_{h_2, \ldots, h_s}\mu_{H_2}(h_2) \cdots \mu_{H_s}(h_s)\norm{\Delta_{{\textbf{v}}_2 h_2, \ldots, {\textbf{v}}_s h_s} f}_{{\textbf{v}}_1\cdot[\pm H_1]}^2\\
