A \emph{nilmanifold} of degree $k$, step $s$, complexity at most $M$, and dimension $m$ consists of the following data:
\begin{enumerate}
    \item an $s$-step connected and simply connected nilpotent real Lie group $G$ and a discrete cocompact subgroup $\Gamma$ of $G$;
    \item a \emph{filtration} $G_\bullet = (G_i)_{i = 0}^\infty$ of nested subgroups $G = G_0=G_1 \supseteq G_2 \supseteq \cdots$ such that $G_{i}=\{\mathrm{Id}_G\}$ for all $i>k$ and $[G_i,G_j] \subseteq G_{i+j}$ for all $i,j$; and
    \item a \emph{Mal'cev basis}, i.e., a basis $\{X_1, \dots, X_m\}$ of the Lie algebra $\mathfrak{g} := \log(G)$.
\end{enumerate}
We furthermore require the data to satisfy the following conditions:
\begin{enumerate}
    \item For $1 \le i, j \le m$, we have
    $$[X_i, X_j] = \sum_{l > \max(i, j)} a_{ijl} X_l$$
    for some rational numbers $a_{ijl}$ of height at most $M$.
    \item For $m_i := \text{dim}(G_i)$, we have $\log(G_i) = \text{span}\{X_j: m - m_i < j \le m\}$.
    \item Each element $g \in G$ can be expressed uniquely as $\exp(t_1X_1)\exp(t_2X_2) \cdots \exp(t_mX_m)$ with $t_1, \dots, t_m \in \mathbb{R}$; we let $\psi: g \mapsto (t_1, \ldots, t_m)$ denote the associated \emph{coordinate map} from $G$ to $\mathbb{R}^m$.
    \item $\Gamma$ consists of precisely the elements $g$ for which $\psi(g) \in \mathbb{Z}^m$.
\end{enumerate}
A Mal'cev basis that satisfies the last three of these conditions is said to be \textit{adapted} to the filtration $G_\bullet$.

\label{def:smoothness}
Let $p(x)=\sum_{j=0}^D \alpha_j x^j \in \mathbb{R}[x]$ be a polynomial of degree $D$.  Its \emph{smoothness norm} at scale $T>0$ is defined to be
$$\norm{p}_{C^\infty[T]}:=\max_{1 \leq j \leq D}T^{j} \norm{\alpha_j}_{\mathbb{R}/\mathbb{Z}}.$$

\label{extrapolation}
    Let $D, Q, T\in{\mathbb N}$, let $R\in{\mathbb R}[z]$ be a polynomial of degree $D$, and let $a, b \in {\mathbb Z}$ with $|a| \le QT$ and $0<|b| \leq Q$ nonzero. Then the polynomial $\tilde{R}(z):= R(a + bz)$ satisfies 
    $$\|b^D R\|_{C^\infty[T]} \ll_D Q^{D-1}\|\tilde{R}\|_{C^\infty[T]}.$$

Assume that $\|\tilde{R}\|_{C^\infty[T]} \le M$; we will show that $\|b^D R\|_{C^\infty[T]} \ll_D Q^{D-1} M$.  Write $R(z) = \sum_{i = 0}^D \alpha_i z^i$. Then
    \begin{align*}
        \tilde R(z)=R(a + bz) = \sum_{i = 0}^D \alpha_i (a + bz)^i = \sum_{i = 0}^D \alpha_i \sum_{j = 0}^i {i \choose j} b^jz^{j} a^{i - j} = \sum_{j =0}^D b^jz^{j} \sum_{i=j}^D \alpha_i {i \choose j} a^{i - j}.    
    \end{align*}
     The assumption $\|\tilde{R}\|_{C^\infty[T]} \le M$ means that
     \begin{align}\label{E: R/Z equations}
         \norm{b^j\cdot \sum_{i=j}^D  \alpha_i {i \choose j} a^{i - j}}_{\mathbb{R}/\mathbb{Z}} \le M/T^{j}
     \end{align}
    for each $1 \leq j \leq D$.  In particular the $j=D$ instance of \eqref{E: R/Z equations} gives $$\norm{b^D \alpha_D}_{{\mathbb R}/{\mathbb Z}} \leq M/T^D.$$
    Next, the $j=D-1$ instance of \eqref{E: R/Z equations} gives $$\norm{b^{D-1}(\alpha_{D-1}+Da\alpha_D)}_{{\mathbb R}//Z} \leq M/T^{D-1};$$
    multiplying the expression in $\norm{\cdot}_{{\mathbb R}/{\mathbb Z}}$ by $b$ and using the triangle inequality (and the assumption on the sizes of $a,b$), we find that
    $$\norm{b^D \alpha_{D-1}}_{{\mathbb R}/{\mathbb Z}} \leq QM/T^{D-1}+D(QT)(M/T^D) \ll_D QM/T^{D-1}.$$
    Continuing inductively in this manner, we find that
    $$\norm{b^D \alpha_{j}}_{{\mathbb R}/{\mathbb Z}} \ll_D Q^{D-j}M/T^j \leq Q^{D-1}M/T^j$$
    for each $1 \leq j \leq D$, as desired.

\begin{align*}
        \tilde R(z)=R(a + bz) = \sum_{i = 0}^D \alpha_i (a + bz)^i = \sum_{i = 0}^D \alpha_i \sum_{j = 0}^i {i \choose j} b^jz^{j} a^{i - j} = \sum_{j =0}^D b^jz^{j} \sum_{i=j}^D \alpha_i {i \choose j} a^{i - j}.    
    \end{align*}

\begin{align}\label{E: R/Z equations}
         \norm{b^j\cdot \sum_{i=j}^D  \alpha_i {i \choose j} a^{i - j}}_{\mathbb{R}/\mathbb{Z}} \le M/T^{j}
     \end{align}

\begin{align*}
R(\widetilde P_{[r, V]}(z)) &=\sum_{i = 0}^D \alpha_i (V_d z^d+\cdots +V_1 z)^i  \\
 &=\sum_{i = 0}^D \alpha_i \sum_{j_1+\cdots+j_d=i}\binom{i}{j_1, \ldots, j_d}(V_1z)^{j_1}\cdots (V_d z^d)^{j_d}\\
 &=\sum_{k=0}^{dD} z^k \sum_{i = 0}^D \alpha_i  \sum_{{\underline{j}} \in \mathcal{P}(i,k)}\binom{i}{j_1, \ldots, j_d}V_1^{j_1}\cdots V_d^{j_d},
