For $\xi\in{\mathbb R}/{\mathbb Z}$, we also let
\begin{align*}
    S(\xi) := \sum_{z\in[K]}e(\xi \widetilde{P}_{[r, V]}(z))
\end{align*}
denote the Fourier transform of the (multi)set $\widetilde{P}_{[r, V]}([K])$.

For coprime $0\leq a < q \leq K^\varepsilon$, we define the \emph{major arc}
\begin{align*}
    \mathfrak{M}_{a,q} := \left\{\xi\in{\mathbb R}/{\mathbb Z}:\; \abs{\xi - \frac{a}{q}}\leq K^{-(d-\varepsilon)}\right\}.
\end{align*}

\label{L: 4-th moment}
    There exists some positive integer $s_0(d) > d$ such that for all $s\geq s_0(d)$ and $\eta >0$, we have
    \begin{align*} 
        \int_{{\mathbb R}/{\mathbb Z}}\abs{S(\xi)}^{2s}\; d\xi  \ll_\eta K^{2s - d +\eta}.
    \end{align*}

\label{L: minor arcs}
    Let $s_0(d)$ be as in Lemma \ref{L: 4-th moment}, and let $s> s_0(d)$ be a positive integer. There exists an absolute $C=C(d)\geq 1$ such that for all $\varepsilon\in(0,1)$
    and positive integers $K\gg_{d,\varepsilon} 1$, if the coefficients of $\widetilde{P}_{[r, V]}$ have size at most $K^{\varepsilon/4}$, then 
    we have the pointwise bound
    \begin{align*}
        \sup_{\xi\in\mathfrak{m}}|S(\xi)|
        \leq K^{1-\varepsilon/C}
    \end{align*}
    as well as the $L^{2s}$-bound
    \begin{align*}
        \int_\mathfrak{m}\abs{S(\xi)}^{2s}
        \ll_{s, \varepsilon}K^{2s-d-\varepsilon/C}.
    \end{align*}

\label{L: major arc expression}
    Let $0<\varepsilon<1/3$ and $0\leq a < q \leq K^\varepsilon$ with $a,q$ coprime.
    If $\xi\in\mathfrak{M}_{a,q}$, then 
    \begin{align*}
        S(\xi)
        = \mathbb{E}_{u\in[q]}e(a \widetilde{P}_{[r, V]}(u)/q)\int_0^K e\brac{\brac{\xi-\frac{a}{q}}\widetilde{P}_{[r, V]}(z)}dz + O(K^{2\varepsilon}).
    \end{align*}

\label{L: S(a,q)}
    Let $1\leq a < q$ be coprime positive integers.  
    Then 
    \begin{align*}
        |S(a,q)|\ll_{\eta, P} q^{\eta - 1/d}\quad \textrm{for\; every}\quad \eta>0.
    \end{align*}
    Moreover, $S(a,q) = 0$ whenever $\gcd(q, W)>1$.

\label{L: integral bound}
    We have
    \begin{align*}
        \abs{\int_0^K e(\xi \widetilde{P}_{[r, V]}(z))\; dz}\ll_P 1 + |\xi|^{-1/d}V_d^{-1/d}.
    \end{align*}

\label{L: major arcs}
    For $s>d$ and $\varepsilon\in (0, 1/10]$, we have
    \begin{align*}
        \int_\mathfrak{M}\abs{S(\xi)}^{2s}\; d\xi \ll_{P, s} \frac{K^{2s-d}}{V_d}
    \end{align*}
    as long as $K\geq V_d^2$.

We let all constants depend on $P, s$.
Applying Lemma \ref{L: major arc expression}, integrating over all of the major arcs, and changing variables $\xi\mapsto \xi + a/q$ on each $\mathfrak{M}_{a,q}$, we have  
\begin{multline*}
    \int_\mathfrak{M}\abs{S(\xi)}^{2s}\; d\xi = \Bigbrac{1_{(a,q)=(0,1)} + \sum_{\substack{1\leq a < q\leq K^\varepsilon,\\ \gcd(a,q) = 1}}
    |S(a,q)|^{2s}}\cdot\int_{-K^{-d+\varepsilon}}^{K^{-d+\varepsilon}} \abs{\int_0^K e\brac{{\xi}\widetilde{P}_{[r, V]}(z)} \,dz}^{2s}\, d\xi\\
    +O\Bigbrac{1_{(a,q)=(0,1)} + \sum_{\substack{1\leq a < q\leq K^\varepsilon,\\ \gcd(a,q) = 1}}1}(K^{2s-1-d+3\varepsilon}).
\end{multline*}

We bound the terms in the expression above one by one, starting with  the contribution of the sums $S(a,q)$. For every $\eta>0$, we can bound
\begin{align*}
    1_{(a,q)=(0,1)} + \sum_{\substack{1\leq a < q\leq K^\varepsilon,\\ \gcd(a,q) = 1}}|S(a,q)|^{2s}\ll_{\eta} 1 +  \sum_{\substack{1\leq a < q\leq K^\varepsilon,\\ \gcd(a,q) = 1}}q^{\eta -2s/d}\ll_\eta 1 + K^{\varepsilon(\eta + 2-2s/d)},
\end{align*}
where the first inequality follows from an application of Lemma \ref{L: S(a,q)} with $2\eta s$ in place of $\eta$, and the second bound follows from trivially estimating the number of $a$'s in $1\leq a < q$ by $q$ and then trivially bounding $q\leq K^\varepsilon$. 
Importantly, this expression is $O(1)$ as long as $s>d$ and $\eta<2/d$. Since there are no further restrictions on the choice of $\eta$, we can take any $\eta$ in the range above. 

To bound the contribution of the integral, we split it over $\xi$ at $K^{-d}/V_d$, obtaining
\begin{multline*}
    \int_{-K^{-d+\varepsilon}}^{K^{-d+\varepsilon}} \abs{\int_0^K e\brac{\xi \widetilde{P}_{[r, V]}(z)}dz}^{2s} d\xi\\ \leq \int_{-K^{-d}/V_d}^{K^{-d}/V_d} K^{2s}\, d\xi + 2 \int_{K^{-d}/V_d}^1 \abs{\int_0^K e\brac{\xi \widetilde{P}_{[r, V]}(z)}dz}^{2s}\, d\xi.
\end{multline*}
The first term can be bounded trivially by $K^{2s-d}/V_d$. To bound the second term, we apply Lemma \ref{L: integral bound}, which gives
\begin{align*}
    \int_{K^{-d}/V_d}^1 \abs{\int_0^K e\brac{\xi \widetilde{P}_{[r, V]}(z)}dz}^{2s}\, d\xi
    &\ll \int_{K^{-d}/V_d}^1 |\xi|^{-2s/d}V_d^{-2 s/d} d\xi\ll  \frac{K^{2s-d}}{V_d},
\end{align*}
where we use Lemma \ref{L: integral bound} to bound the integrand and the assumption $s>d$ to ensure that the exponent is of the right order. 

Lastly, the error term is at most
\begin{align*}
    \ll\Bigbrac{1_{(a,q)=(0,1)} + \sum_{\substack{1\leq a < q\leq K^\varepsilon,\\ \gcd(a,q) = 1}}1}K^{2s-1-d+3\varepsilon}\ll K^{2s-1-d+5\varepsilon},
\end{align*}
which can be bounded by $\ll K^{2s-d}/V_d$ since $K\geq V_d^2$ and $\varepsilon\leq 1/10$.

\begin{multline*}
    \int_\mathfrak{M}\abs{S(\xi)}^{2s}\; d\xi = \Bigbrac{1_{(a,q)=(0,1)} + \sum_{\substack{1\leq a < q\leq K^\varepsilon,\\ \gcd(a,q) = 1}}
    |S(a,q)|^{2s}}\cdot\int_{-K^{-d+\varepsilon}}^{K^{-d+\varepsilon}} \abs{\int_0^K e\brac{{\xi}\widetilde{P}_{[r, V]}(z)} \,dz}^{2s}\, d\xi\\
    +O\Bigbrac{1_{(a,q)=(0,1)} + \sum_{\substack{1\leq a < q\leq K^\varepsilon,\\ \gcd(a,q) = 1}}1}(K^{2s-1-d+3\varepsilon}).
\end{multline*}

\begin{align*}
    1_{(a,q)=(0,1)} + \sum_{\substack{1\leq a < q\leq K^\varepsilon,\\ \gcd(a,q) = 1}}|S(a,q)|^{2s}\ll_{\eta} 1 +  \sum_{\substack{1\leq a < q\leq K^\varepsilon,\\ \gcd(a,q) = 1}}q^{\eta -2s/d}\ll_\eta 1 + K^{\varepsilon(\eta + 2-2s/d)},
\end{align*}

