    \int_{-K^{-d+\varepsilon}}^{K^{-d+\varepsilon}} \abs{\int_0^K e\brac{\xi \widetilde{P}_{[r, V]}(z)}dz}^{2s} d\xi\\ \leq \int_{-K^{-d}/V_d}^{K^{-d}/V_d} K^{2s}\, d\xi + 2 \int_{K^{-d}/V_d}^1 \abs{\int_0^K e\brac{\xi \widetilde{P}_{[r, V]}(z)}dz}^{2s}\, d\xi.
\end{multline*}

\label{P: even moment bound}
    There exists $s_1(d)\in{\mathbb N}$ and $C=C(d)>0$ such that if $s\geq s_1(d)$ and $N\geq V_d^{C}$, then
        \begin{align*}
        \int_{{\mathbb R}/{\mathbb Z}}|S(\xi)|^{2s}\; d\xi \ll_{P, s} \frac{K^{2s}}{N}.
    \end{align*}

Let $s_1(d) = \max(s_0(d), d+1)$, where $s_0$ comes from Lemma \ref{L: minor arcs} and $d+1$ is the smallest possible $s$ allowed by Lemma \ref{L: major arcs}. We fix $s>s_1(d)$ and let all the implicit constants depend on $P, s$.
We split ${\mathbb R}/{\mathbb Z}$ into major and minor arcs with  $\varepsilon = 1/10$.
Then we can use Lemma \ref{L: minor arcs} to bound the minor arc contribution as 
\begin{align*}
    \int_{\mathfrak{m}}|S(\xi)|^{2s}\; d\xi \ll K^{2s-d-\varepsilon/C_1} 
\end{align*}
where $C_1>0$ is the constant from Lemma \ref{L: minor arcs}. Since $N = K^d V_d$, this can be bounded by $\ll \frac{K^{2s}}{N}$ as long as $V_d\leq K^{\varepsilon/C_1}$, which we can assume by taking the implicit constant in $N\geq V_d^{\Omega(1)}$ to be sufficiently large. We also implicitly use the assumption $N\geq V_d^{\Omega(1)}$ to ensure that $K^{\varepsilon/4}\geq V_d$ so that the assumption on the coefficients of $\widetilde{P}_{[r, V]}$ in Lemma \ref{L: minor arcs} is satisfied. To bound the major arc contribution by the same final expression, we simply apply Lemma \ref{L: major arcs}.

\label{P: major arc control}
    For every $C_1>0$ there exists $C_2 = C_2(C_1, P)>0$ such that the following holds. Let $\delta\in(0, 1/10)$, let $V\leq W^{C_1}$ be a nonnegative integer power of $W$, let $r\in[V]$, and let $N\geq C_2 V_d^{C_2} \delta^{-C_2}$ be an integer. Let $f_0,f_1:{\mathbb Z}\to{\mathbb C}$ be $1$-bounded functions supported on $[N]$. If
    \begin{align}\label{E: Sarkozy input}
        \abs{\sum_x \mathbb{E}_{z\in [K]}f_0(x)f_1(x+\widetilde{P}_{[r, V]}(z))}\geq \delta N,
    \end{align}
    then for every $i=0,1$ there exist phases $\xi_i\in{\mathbb R}/{\mathbb Z}$ and positive integers $q_i\ll_{C_1, P} \delta^{-O_{C_1, P}(1)}$ such that $\norm{q_i\xi_i}_{{\mathbb R}/{\mathbb Z}}\ll_{C_1, P}\delta^{-O_{C_1, P}(1)}/N$ and $|\widehat{f_i}(\xi_i)|\gg_{C_1, P} \delta^{O_{C_1, P}(1)}N$.

  We fix $C_1>0$ and let all constants depend on $P$.
  We prove the bound only for $i=0$, since one can then deduce the result for $i=1$ by shifting $x \mapsto x-\widetilde{P}_{[r, V]}(z)$ and exchanging the roles of $f_0,f_1$. Our first goal is to show that the largeness of \eqref{E: Sarkozy input} implies the largeness of some Fourier coefficient of $f_0$, and then we use the fraction comparison argument to deduce that this Fourier coefficient must be a major arc.

  Define the mutliset $E:= \{\widetilde{P}_{[r, V]}(z):\; z\in[K]\}$, so that our assumption can be expressed as
  \begin{align*}
      \abs{\sum_{x,z}f_0(x) f_1(x+z)1_E(z)}\geq \delta NK.
  \end{align*}
Note that $F = \widehat{1_E}$.  Now, Fourier-expanding, extracting the largest Fourier coefficient, and applying the triple H\"older inequality (with exponents $\frac{2s}{s-1}, 2, 2s$) followed by Parseval's Identity,
  we get
  \begin{align*}
      \delta N K &\leq \norm{\widehat{f_0}}_\infty^{1/s}\cdot \int_{{\mathbb R}/{\mathbb Z}}|\widehat{f_0}(\xi)|^{1-1/s}\cdot|\widehat{f_1}(\xi)|\cdot|F(\xi)|\; d\xi\\
      &\leq \norm{\widehat{f_0}}_\infty^{1/s}\cdot \norm{f_0}^{1-1/s}_2 \cdot \norm{f_1}_2 \cdot \brac{\int_{{\mathbb R}/{\mathbb Z}}|F(\xi)|^{2s}\; d\xi}^{1/(2s)}
  \end{align*}
  for any $s\geq 2$.
  We can trivially bound $\norm{f_0}^{1-1/s}_2 \cdot \norm{f_1}_2\leq N^{(2s-1)/(2s)}$, and Proposition \ref{P: even moment bound} gives
  \begin{align*}
      \int_{{\mathbb R}/{\mathbb Z}}|S(\xi)|^{2s}\; d\xi \ll \frac{K^{2s}}{N}
  \end{align*}
