\end{align}
Let $R(z):= q\theta(Vz + \widetilde P(r'))$, so that $R\circ \widetilde P_{[r',V]}(z) = q\theta\widetilde P(Vz +r')$. Setting $T=N/V$ and recalling that $V_d = W_d V^{d-1}$, we can write the estimate \eqref{E: Fourier uniformity estimate} as
\begin{align*}
    \norm{R\circ \widetilde P_{[r',V]}}_{C^\infty [(T/V_d)^{1/d}]} \ll w^{O(c)}.
\end{align*}
Lemma \ref{lem:composing-polynomials-2} then gives
\begin{align*}
    \norm{qV\theta}_{{\mathbb R}/{\mathbb Z}}\ll \frac{V w^{O(c)}}{N}.
\end{align*}
Hence the $\tilde{\nu}$-contribution is $\ll N/(V w^c)$ unless there is some positive integer $q \ll w^{O(c)}$ such that $\norm{qV\theta}_{\mathbb{R}/\mathbb{Z}} \ll Vw^{O(c)}/N$.


